let slides = document.querySelectorAll('.slide');
let currentIndex = -1;
let totalSlides = slides.length;
let sidePanelHidden = false;
let slideTimer = null;

// Configuration
const config = {
    showCounter: true,
    showProgress: true,
    autoSlide: false,
    autoSlideDelay: 5000,
    keyboardNav: true
};

// Initialize
init();

function init() {
    setupEventListeners();
    setActiveSlide(0);
    updateProgress();
}

function setupEventListeners() {
    // Keyboard navigation
    if (config.keyboardNav) {
        document.addEventListener('keydown', handleKeydown);
    }

    // Window resize
    let resizeTimer;
    window.addEventListener('resize', () => {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(() => {
            if (sidePanelHidden && window.innerWidth > 768) {
                toggleSidePanel();
            }
        }, 100);
    });

    // Auto-slide timer if enabled
    if (config.autoSlide) {
        startAutoSlide();
    }
}

function handleKeydown(e) {
    if (!config.keyboardNav) return;

    switch (e.key) {
        case 'ArrowRight':
        case 'ArrowDown':
        case ' ':
        case 'Enter':
            if (currentIndex < totalSlides - 1) {
                showSlide(currentIndex + 1);
                if (!!slideTimer !== true) {
                    startAutoSlide();
                }
            }
            break;

        case 'ArrowLeft':
        case 'ArrowUp':
            if (currentIndex > 0) {
                showSlide(currentIndex - 1);
                clearTimeout(slideTimer);
            }
            break;

        case 'Home':
            showSlide(0);
            break;

        case 'End':
            showSlide(totalSlides - 1);
            break;

        case 't':
        case '?':
            toggleSidePanel();
            break;

        case 'Escape':
            closeCurrentSlide();
            break;
    }
    e.preventDefault();
}

function showSlide(index) {
    if (index < 0 || index >= totalSlides) return false;

    // Clear auto-slide timer
    clearTimeout(slideTimer);
    slideTimer = null;

    // Scroll to top
    window.scrollTo({ top: 0, behavior: 'smooth' });

    // Update active slide
    slides.forEach((slide, i) => {
        slide.classList.toggle('active', i === index);
    });

    // Update side panel
    updateSidePanelActive(index);

    // Update nav state
    currentIndex = index;
    updateNavButtons();
    updateProgress();

    return true;
}

function setActiveSlide(index) {
    showSlide(index);
}

function updateNavButtons() {
    const btnPrev = document.getElementById('btn-prev');
    const btnNext = document.getElementById('btn-next');
    const btnTop = document.getElementById('btn-top');
    const btnClose = document.getElementById('btn-close');

    if (btnPrev) btnPrev.disabled = currentIndex === 0;
    else btnPrev = null;

    if (btnNext && totalSlides > 1) {
        btnNext.disabled = currentIndex === totalSlides - 1;
    }
    else btnNext = null;

    if (btnTop) btnTop.disabled = false;
    else btnTop = null;

    if (btnClose) btnClose.disabled = currentIndex === -1;
    else btnClose.disabled = currentIndex === -1;
}

function updateProgress() {
    const progressBar = document.getElementById('progress-bar');
    const counter = document.getElementById('slide-counter');

    if (config.showProgress && progressBar) {
        const percentage = (currentIndex + 1) / totalSlides * 100;
        progressBar.style.width = `${percentage}%`;
    }

    if (config.showCounter && counter && totalSlides > 0) {
        counter.textContent = `Slide ${currentIndex + 1} of ${totalSlides}`;
    }
}

function startAutoSlide() {
    if (config.autoSlide && !!slideTimer !== true) {
        slideTimer = setTimeout(() => {
            if (currentIndex < totalSlides - 1) {
                showSlide(currentIndex + 1);
            } else {
                slideTimer = null;
                clearTimeout(slideTimer);
            }
        }, config.autoSlideDelay);
    }
}

function stopAutoSlide() {
    slideTimer = null;
    clearTimeout(slideTimer);
}

