document.addEventListener('DOMContentLoaded', function() {
  var slides  = document.querySelectorAll('.slide'),
      toc     = document.getElementById('toc'),
      counter = document.getElementById('counter'),
      nextBtn = document.getElementById('next'),
      prevBtn = document.getElementById('prev'),
      main    = document.querySelector('.main'),
      sidebar = document.querySelector('.sidebar'),
      current = 0,
      total   = slides.length,
      timer   = null;

  // Generate TOC
  slides.forEach(function(s,i) {
    var li = document.createElement('li');
    li.textContent = i + 1;
    li.onclick = function() { gotoSlide(i); };
    toc.appendChild(li);
  });

  // Update slide visibility
  function update() {
    slides.forEach(function(s,i) {
      s.classList.toggle('active', i === current);
    });
    counter.textContent = (current + 1) + ' / ' + total;
    main.setAttribute('data-sidebar', sidebar ? '' : 'closed');
    main.setAttribute('data-sidebar', sidebar.style.display === 'none' ? 'closed' : 'open');
  }

  // Go to slide
  function gotoSlide(n) {
    if (n < 0) n = total - 1;
    if (n >= total) n = 0;
    current = n;
    if (timer) clearInterval(timer);
    timer = setInterval(next, 3000);
    update();
  }

  // Next slide
  function next() {
    current = current >= total - 1 ? 0 : current + 1;
    update();
  }

  // Prev slide
  function prev() {
    current = current === 0 ? total - 1 : current - 1;
    update();
  }

  // Toggle sidebar
  function toggleSidebar() {
    sidebar.style.display = sidebar.style.display === 'none' ? 'block' : 'none';
    main.setAttribute('data-sidebar', sidebar.style.display === 'none' ? 'closed' : 'open');
  }

  // Events
  nextBtn.addEventListener('click', next);
  prevBtn.addEventListener('click', prev);

  main.addEventListener('click', function(e) {
    if (e.target === nextBtn) next();
    if (e.target === prevBtn) prev();
  });

  // Sidebar toggle
  sidebar.addEventListener('click', function(e) {
    if (e.target === sidebar) toggleSidebar();
  });

  // Auto-play on mouse up
  document.addEventListener('mousedown', function() {
    if (timer) clearInterval(timer);
  });

  document.addEventListener('mouseup', function() {
    timer = setInterval(next, 3000);
  });

  // Keyboard
  document.addEventListener('keydown', function(e) {
    if (e.target && e.target.tagName === 'INPUT') return;
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === 'Enter') { next(); e.preventDefault(); }
    if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { prev(); e.preventDefault(); }
