var prevBtn=document.getElementById('prev');
var main=document.querySelector('.main');
var total=slides.length;
var current=0;
var timer=null;

function renderTOC(){
  var frag=document.createDocumentFragment();
  slides.forEach(function(s,i){
    var li=document.createElement('li');
