function prev(){gotoSlide(current-1);}
function toggleSidebar(){
  var sib=document.querySelector('.sidebar');
  sib.style.display=sib.style.display==='none'?'block':'none';
  main.setAttribute('data-closed',sib.style.display==='none'?'true':'false');
}

