document.addEventListener('keydown',function(e){
  if(e.target.tagName==='INPUT')return;
  if(e.key==='ArrowRight'||e.key==='ArrowDown'||e.key==='Enter'){gotoSlide(current+1);e.preventDefault();}
  if(e.key==='ArrowLeft'||e.key==='ArrowUp'){gotoSlide(current-1);e.preventDefault();}
  if(e.key==='t'||e.key==='T'){toggleSidebar();e.preventDefault();}
  if(e.key=== 'Escape'){if(document.fullscreenElement){document.exitFullscreen();}}
  if(e.key==='Home'){gotoSlide(0);e.preventDefault();}
  if(e.key==='End'){gotoSlide(total-1);e.preventDefault();}
});

document.addEventListener('touchstart',function(e){touchStart=e.changedTouches[0].screenY;mouseDown=true;});
document.addEventListener('touchend',function(e){touchEnd=e.changedTouches[0].screenY;if(touchEnd-touchStart>50)prev();if(touchStart-touchEnd>50)next();touchStart=0;mouseDown=false;});

renderTOC();
update();
})();
