html,body{height:100%;overflow:hidden;font-family:system-ui,-apple-system,sans-serif;background:var(--b);color:var(--t)}
.app{display:flex;flex-direction:column;height:100%;padding:0.5rem}
.header{display:flex;align-items:center;padding:0.5rem 1rem;gap:0.5rem;background:var(--b);border-bottom:1px solid #374151}
.logo{font-weight:700;font-size:1.1rem;color:var(--p);white-space:nowrap}
.main{flex:1;display:flex;overflow:hidden;gap:0.5rem}
.sidebar{flex-shrink:0;background:#1f2937;border-right:1px solid #374151;padding:0.75rem;overflow-y:auto;display:flex;flex-direction:column;gap:0.5rem;border-radius:4px;flex:0 0 auto;overflow:hidden}
.sidebar[hidden]{display:none}
.slide-panel{flex:1 1 auto;display:flex;flex-direction:column;overflow:hidden;gap:0.5rem}
.sliding{overflow-y:auto;display:flex;flex-direction:column;scroll-behavior:smooth}
.slide{padding:1rem;margin:0;background:var(--b);border:none;border-radius:0;color:var(--t);transform:inherit;transition:inherit;opacity:inherit;display:none}
.slide.active{display:flex;flex-grow:1;border-radius:0}
.slide h1{color:var(--p);font-size:1.5rem;margin-bottom:0.5rem;font-weight:600}
.slide p,.slide ul,.slide button,.slide div{margin:0.5rem 0;line-height:1.4}
.slide ul{list-style:disc;padding-left:1.5rem;font-size:0.95rem}
.slide button{display:inline-block;padding:0.4rem 0.8rem;margin-top:0.5rem;background:var(--p);color:white;border:none;border-radius:4px;cursor:pointer;font-weight:600;font-size:0.9rem}
.footer{height:auto;padding:0.5rem;background:#111827;border-top:1px solid #374151;display:flex;justify-content:space-between;align-items:center;gap:0.5rem}
.counter{font-size:0.8rem;color:var(--p)}
.nav{display:flex;gap:0.5rem}
.nav button{padding:0.3rem;background:var(--p);color:white;border:none;border-radius:4px;font-weight:600;font-size:0.8rem;min-width:32px}
.reload-hint{position:fixed;bottom:6px;left:50%;transform:translateX(-50%);background:var(--p);color:#e5e7eb;padding:0.25rem 0.5rem;border-radius:3px;font-size:0.8rem;font-weight:700;z-index:100;white-space:nowrap}
.slide-panel::-webkit-scrollbar{width:4px}
.slide-panel::-webkit-scrollbar-track{background:transparent}
.slide-panel::-webkit-scrollbar-thumb{background:#4b5563;border-radius:2px}
/* Responsive */
@media(max-width:768px){
  .app{padding:0.25rem}
  .logo{font-size:0.9rem}
  .sidebar{padding:0.5rem;display:none;background:#111827;border:none}
  .main[data-closed="true"] .sidebar{width:auto}
  .main[data-closed="true"] .slide-panel{width:100%}
  .main[data-closed="true"] .slide-panel{margin-left:0}
  .slide h1{font-size:1.25rem}
  .nav button{min-width:28px}
}
@media(max-width:480px){
  .reload-hint{bottom:4px;left:auto;right:6px;padding:0.2rem 0.4rem}
}
</style>
</head>
<body>
<div class="app">
<header class="header"><div class="logo">📊 SlideShow</div></header>
<main class="main" data-closed="false">
<aside class="sidebar"><div style="padding:0.5rem 0;font-weight:600;color:#e5e7eb">Slides</div><div id="toc"></div></aside>
<div class="slide-panel">
<div class="sliding">
<section id="slide-0" class="slide active"><h1>1. Welcome</h1><p>Welcome to the slide show.<br>Click <b>Next</b> to navigate.</p></section>
<section id="slide-1" class="slide"><h1>2. Features</h1><ul><li>📱 Fully responsive</li><li>🎯 Precise control</li><li>💾 No automatic slides</li><li>🎨 Clean design</li></ul></section>
<section id="slide-2" class="slide"><h1>3. About</h1><p>Built for Blender<br>development.<br>Mobile-first design.</p></section>
<section id="slide-3" class="slide"><h1>4. Navigation</h1><div><b>Next/Prev</b> Navigate</div><div><b>N</b> Toggle sidebar</div><div><b>Home</b> First</div><div><b>End</b> Last</div><div><b>Space</b> Next</div></section>
<section id="slide-4" class="slide"><h1>5. Tips</h1><div>• Click sidebar to close</div><div>• Use keyboard arrows</div><div>• Resize window</div></section>
<section id="slide-5" class="slide"><h1>6. Complete!</h1><p>All systems ready!<br>🎉<br><br><b>Enjoy your slides!</b></p></section>
</div>
</div>
<footer class="footer">
<div class="counter" id="counter">1 / 6</div>
<nav class="nav">
<button id="prev">←</button><button id="next">→</button>
</nav>
</footer>
<div class="reload-hint">🔄 Press <b>Ctrl+R</b></div>
</main>
</div>
<script>
(function(){
var slides=document.querySelectorAll('.slide'),
    toc=document.getElementById('toc'),
    counter=document.getElementById('counter'),
    nextBtn=document.getElementById('next'),
    prevBtn=document.getElementById('prev'),
    main=document.querySelector('.main'),
    sidebar=document.querySelector('.sidebar'),
    total=slides.length,
    current=0;

// Generate TOC
toc.innerHTML='';
slides.forEach(function(s,i){
  var li=document.createElement('li');
  li.textContent=i+1;
  li.onclick=function(){gotoSlide(parseInt(this.previousElementSibling.id.split('-')[1]));};
  toc.appendChild(li);
});

// Hide sidebar button
var btn=document.createElement('button');
btn.textContent='-';
btn.title='Hide sidebar';
btn.onclick=toggleSidebar;
sidebar.appendChild(btn);

// Update
function update(){
  slides.forEach(function(s,i){
    if(i===current) s.classList.add('active');
    else s.classList.remove('active');
  });
  counter.textContent=(current+1)+' / '+total;
  main.setAttribute('data-closed',sidebar.style.display==='none'?'true':'false');
}

// Go to slide
function gotoSlide(n){
  var max=total;
  if(n<0)n=max-1;
  if(n>=max)n=max-1;
  current=n;
  update();
}

function next(){current=current>=total-1?0:current+1;update();}
function prev(){current=current===0?total-1:current-1;update();}
function toggleSidebar(){
  if(sidebar.style.display==='none'){
    sidebar.style.display='flex';
    main.setAttribute('data-closed','false');
  } else {
    sidebar.style.display='none';
    main.setAttribute('data-closed','true');
  }
}

// Events
nextBtn.onclick=next;prevBtn.onclick=prev;
sidebar.onclick=toggleSidebar;

// Keyboard
document.addEventListener('keydown',function(e){
  if(e.target.tagName==='INPUT')return;
  if(e.key==='ArrowRight'||e.key==='ArrowDown'||e.key==='Enter'||e.key===' '){gotoSlide(current+1);e.preventDefault();}
  if(e.key==='ArrowLeft'||e.key==='ArrowUp'){gotoSlide(current-1);e.preventDefault();}
  if(e.key==='t'||e.key==='T'||e.key==='n'||e.key==='N'){toggleSidebar();e.preventDefault();}
  if(e.key==='Escape'&&document.fullscreenElement){document.exitFullscreen();e.preventDefault();}
  if(e.key==='Home'){current=0;update();e.preventDefault();}
  if(e.key==='End'){current=total-1;update();e.preventDefault();}
});

update();
})();
</script>
</body>
</html>'''
